"""Build an original manuscript and scientific figures from measured JSON results.

No result is hard-coded into the paper: missing experiment summaries stop this job.
"""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'output/research'


def read(path):
    return json.loads(path.read_text(encoding='utf8'))


def number(x,d=4):
    if x is not None and 0 < x < .5*10**(-d):return '<'+f'{10**(-d):.{d}f}'
    return 'NA' if x is None else f'{x:.{d}f}'


def table(headers, rows):
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+
                     ['| '+' | '.join(str(v) for v in row)+' |' for row in rows])


def figures(ml,rag,retrieval):
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    import numpy as np
    folder=DATA/'figures';folder.mkdir(exist_ok=True)
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':9,'axes.spines.top':False,'axes.spines.right':False,'savefig.dpi':200})
    fig,axes=plt.subplots(1,2,figsize=(9,3.5),layout='constrained')
    colors=['#087f8c','#d26732']
    for exp,color in zip(ml['experiments'],colors):
        bins=exp['candidates'][exp['selected']]['test']['calibration_bins']
        axes[0].plot([b['predicted'] for b in bins],[b['observed'] for b in bins],marker='o',label='All ages' if exp['cohort']=='all_neonatal_ages' else 'Days 0-2',color=color)
    axes[0].plot([0,1],[0,1],ls='--',color='#777777',lw=1)
    axes[0].set(xlim=(0,1),ylim=(0,1),xlabel='Mean predicted supplied-label probability',ylabel='Observed supplied-label fraction',title='(a) Selected-forest calibration bins')
    axes[0].legend(frameon=False)
    for j,kind in enumerate(['logistic','forest']):
        vals=[e['candidates'][kind]['test']['brier'] for e in ml['experiments']]
        axes[1].bar(np.arange(2)+(j-.5)*.32,vals,width=.32,color=colors[j],label=kind.title())
    axes[1].set(xticks=[0,1],xticklabels=['All ages','Days 0-2'],ylabel='Brier score (lower is better)',title='(b) Held-out supplied-label classification')
    axes[1].legend(frameon=False)
    for ext in ['png','svg']:fig.savefig(folder/f'ml_results.{ext}')
    plt.close(fig)
    fig,axes=plt.subplots(1,2,figsize=(9,3.6),layout='constrained')
    labels=['BM25','Dense','Hybrid','Hybrid +\nconcepts']
    for j,k in enumerate(['recall_at_4','mrr_at_4']):
        axes[0].bar(np.arange(4)+(j-.5)*.35,[v[k] for v in retrieval['summary'].values()],width=.35,color=colors[j],label='Recall@4' if j==0 else 'MRR@4')
    axes[0].set(xticks=range(4),xticklabels=labels,ylim=(0,1.05),title='(a) Engineering-reference retrieval')
    axes[0].legend(frameon=False)
    names=['Without verification','Verified: all cases','Verified: released only']
    arms=[rag['arms'][k] for k in ['without_verification','with_verification_all_cases','with_verification_released_only']]
    for j,k in enumerate(['bert_f1','roberta_f1']):
        values=[a['metrics'][k] for a in arms]
        axes[1].bar(np.arange(3)+(j-.5)*.32,[v or 0 for v in values],width=.32,color=colors[j],label='DistilBERT F1' if j==0 else 'RoBERTa F1')
        for i,v in enumerate(values):
            if v is None:axes[1].text(i,0.03,'NA',ha='center',fontsize=8)
    axes[1].set(xticks=range(3),xticklabels=['Unverified','Verified\nall cases','Verified\nreleased only'],ylim=(0,1.05),ylabel='Unrescaled BERTScore F1',title=f'(b) Release coverage: {rag["released"]}/{rag["n"]}')
    axes[1].legend(frameon=False)
    for ext in ['png','svg']:fig.savefig(folder/f'rag_results.{ext}')
    plt.close(fig)


def main():
    ml=read(DATA/'ml_summary.json');audit=ml['audit']
    rag=read(DATA/'rag_v2/summary.json');retrieval=read(DATA/'rag_v2/retrieval.json')
    initial=[read(p) for p in sorted((ROOT/'output/operational/quote_echo/runs').glob('*.json'))]
    population=read(DATA/'quality_population.json')
    initial=[r for r in initial if r['id'] in population['rag']['eligible_case_ids']]
    if rag['n']!=population['rag_v2']['n']:
        raise ValueError('Recompute paired metrics on the completed-provider population before building the paper')
    cases=read(DATA/'rag_v2/per_case_metrics.json')
    diagnostic=read(DATA/'label_diagnostic.json')
    leakage=read(DATA/'leakage_audit/audit.json')
    ensemble=read(DATA/'ensemble/summary.json')
    figures(ml,rag,retrieval)
    arms=rag['arms'];raw=arms['without_verification'];full=arms['with_verification_all_cases'];released=arms['with_verification_released_only']
    lines=[]
    def add(s):lines.append(s.strip())
    add('# NeoGuard EOS: Longitudinal Evidence Representation, Calibrated Neonatal Label Classification and Verified Guideline-Grounded Generation')
    add('**Original research software report | 25 October 2026 | Reproducible development experiments**')
    add('## Abstract')
    add(f'''Early-onset neonatal sepsis support requires a traceable connection between serial observations, statistical estimates and applicable guideline recommendations. We present NeoGuard EOS, a clinician-facing research application with separate prediction and evidence-generation branches. A temporal findings representation preserves observed measurements, missingness and elapsed-time changes; hybrid retrieval links findings to versioned passages, and a LangGraph workflow subjects generated claims to source and safety auditors. We evaluate supplied-label classification using a user-provided Kaggle CSV with {audit['rows']:,} observations and {audit['patient_ids']:,} identifiers. A data audit exposes conflicting patient/hour records and unstable birth covariates, so these labels are not treated as culture-confirmed EOS and are not used to reconstruct clinical trajectories. Calibrated logistic regression and random forests are trained with patient-disjoint fit, calibration, selection and test partitions. The selected forests achieve test AUROC {number(ml['experiments'][0]['candidates']['forest']['test']['auroc'])} across supplied neonatal ages and {number(ml['experiments'][1]['candidates']['forest']['test']['auroc'])} on postnatal days 0-2. Separately, 18 synthetic vignettes and 12 injected faults examine retrieval, text alignment, model-based judging and release behavior. Hybrid retrieval obtains Recall@4 {number(retrieval['summary']['hybrid']['recall_at_4'])}; concept expansion obtains {number(retrieval['summary']['hybrid_concepts']['recall_at_4'])}. The revised generator produces {rag['generated']}/18 structured drafts, of which {rag['released']}/18 are released after verification. We report lexical and semantic alignment together with abstention coverage, rather than equating text similarity or selective release with clinical correctness.''')
    add('**Keywords:** early-onset neonatal sepsis; temporal evidence; calibrated classification; hybrid retrieval; knowledge graph; LangGraph; claim verification; selective generation.')
    add('## 1. Introduction')
    add('EOS assessment combines maternal risk factors, gestational age, the infant\'s changing condition, cultures and laboratory findings. NICE NG195 and the AAP gestation-specific reports describe different pathways and population boundaries [1-3]. A useful application must distinguish what was observed, what a statistical model estimates, and what a guideline recommends. A low inflammatory-marker value, a reassuring language model response and an unavailable prediction are different states. Combining them into a single opaque score hides the evidence a clinician needs to assess a case.')
    add('The initial application already supported neonatal data entry, serial assessments and guideline search, but relied on a hand-built point score and fallback care-plan text. NeoGuard EOS replaces live score interpretation with a model-artifact contract and an explicit unavailable/abstained state. Its evidence branch uses retrieved passages and verifiable support links. Source availability, model eligibility and authorization are checked independently, and generated content does not become a medication order.')
    add('This report addresses three questions. RQ1 asks what can legitimately be learned from the supplied neonatal table after an identity, outcome and timing audit. RQ2 compares sparse, dense, hybrid and concept-linked retrieval on fixed source-based synthetic questions. RQ3 measures how exact support checks and separate auditing roles alter answer coverage, reference alignment and unsupported-claim exposure. The implementation and study deliberately separate concurrent supplied-label classification from the longer-term objective of forecasting culture-confirmed EOS.')
    add('The contributions are an auditable temporal evidence representation; a patient-disjoint, calibrated research training workflow with portable JSON inference; a reviewed-source retrieval architecture with optional concept links; an immutable quote-ID generation contract; and a reproducible evaluation reporting negative findings and selective-release denominators. Quality comparisons use completed provider calls; operational logs are retained separately. The experiments are development evidence, and the contribution is an implemented integration and failure analysis rather than a claim that any individual component is a newly invented algorithm.')
    add('## 2. Related work and design rationale')
    add('Medical retrieval-augmented generation is sensitive to corpus choice, passage relevance and the relationship between retrieved knowledge and a specific question. MIRAGE studies medical RAG components under a common evaluation framework [5]. HippoRAG explores graph-assisted retrieval for multi-hop knowledge access [6]. These approaches motivate separate retrieval ablations here. NeoGuard\'s optional graph is intentionally narrower: passages are linked to deterministic clinical concept labels. Such links are indexing hints and do not represent causal relationships, verified biomedical facts or patient-specific diagnoses.')
    add('The supplied ADRE manuscript frames clinical report generation as reasoning over an explicit intermediate findings document with source-grounded composition [7]. We adapt that general design idea to serial neonatal observations, without reusing its EEG data, reference reports or numerical findings. Our representation contains observed clinical measurements and time-aware summaries, and the release mechanism uses source-entailment and safety auditing. This differs from an iterative signal-analysis agent: NeoGuard does not autonomously order tests, reinterpret waveforms or repair a rejected answer until it passes.')
    add('BLEU, METEOR, ROUGE and BERTScore provide complementary reference-alignment measures [8-11]. They can reward shared clinical words while missing a dangerous negation, absent condition or wrong population. We therefore pair them with source checks, a fallible model-based judge and deliberate fault injection. TRIPOD+AI motivates transparent reporting of model development, evaluation and intended use [12]; DECIDE-AI motivates distinguishing early software evaluation from evaluation in actual clinical workflows [13]. These frameworks inform reporting, and compliance with their complete checklists is not asserted.')
    add('## 3. Data provenance and quality audit')
    add('The user supplied a ZIP containing one CSV, Neonatal_Sepsis.csv, and a Kaggle description stating that it contains repeated neonatal observations. No dataset URL, original clinical study, collection institution, patient-recruitment criteria, labeling protocol, license or measurement-availability documentation accompanied the file. The archive member is read by its exact name without extracting arbitrary paths. SHA-256 identifies the analyzed CSV: '+audit['csv_sha256']+'. The audit reports aggregate summaries and does not export source patient rows or identifiers.')
    add('Table 1. Supplied CSV integrity and scope.')
    add(table(['Audit item','Measured finding'],[
        ['Observations / supplied identifiers',f"{audit['rows']:,} / {audit['patient_ids']:,}"],
        ['Positive supplied-label observations',f"{audit['positive_rows']:,} ({audit['prevalence']*100:.3f}%)"],
        ['Postnatal-age range','0-28 days'],['Repeated patient/hour rows beyond first',f"{audit['duplicate_patient_hour_rows']:,}"],
        ['Patient/hour pairs with conflicting labels',f"{audit['conflicting_label_patient_hour_pairs']:,}"],
        ['Identifiers with changing gestational age',f"{audit['inconsistent_baseline_patient_ids']['Gestational_Age']:,}"],
        ['Identifiers with changing birth weight',f"{audit['inconsistent_baseline_patient_ids']['Birth_Weight']:,}"],
        ['Identifiers with changing sex',f"{audit['inconsistent_baseline_patient_ids']['Sex']:,}"],
        ['Birth weight at upper recorded value (4.5 kg)',f"{audit['birth_weight_at_upper_value_fraction']*100:.3f}%"],
        ['Missing clinical/laboratory entries per field','3.419%-3.593%']]))
    add('Observation_Hour takes values 1-5, but cannot be assumed to mean hours since birth or a valid availability timestamp. Conflicting records at the same patient/hour and changing immutable birth covariates prevent defensible reconstruction of a single infant trajectory. The analysis does not silently deduplicate, average contradictory records, invent birth timestamps or assign clinician-adjudicated labels. Patient identifiers remain grouping variables for conservative split isolation, but their integrity as true person identifiers is itself uncertain.')
    add('The supplied Sepsis_Label indicates an observation-associated sepsis/non-sepsis state. Culture confirmation, pathogen/contaminant adjudication and event onset are absent. Classification therefore concerns that supplied label at the recorded observation, not a proven future event. A secondary experiment restricts Postnatal_Age to 0, 1 or 2 days to approximate the first-72-hour age window without including ambiguous day-3 records. An age filter cannot convert an unverified label into culture-confirmed EOS. Numeric distributions and high separability motivate investigation of data generation and labeling, but do not establish whether the file is synthetic or clinical.')
    add('Six MIMIC-III v1.4 tables were separately supplied: PATIENTS, ADMISSIONS, ICUSTAYS, D_ITEMS, D_LABITEMS and MICROBIOLOGYEVENTS. The local streaming review identified 7,863 candidate newborn admissions and produced protected adjudication materials. CHARTEVENTS and LABEVENTS were unavailable. A culture entry alone does not establish a complete outcome or control, and admission time is not substituted for exact birth time. MIMIC data were not joined into the Kaggle table or used to fit the reported classifiers. The separate adapter requires reviewed birth times, gestation, units, availability assumptions and labels [4].')
    add('## 4. System architecture and temporal evidence')
    add('[[ARCHITECTURE]]')
    add('The application uses Flutter for case entry and timelines, FastAPI for authorized inference and evidence synthesis, Supabase/PostgreSQL for records and passage indexes, and Groq for language generation. Vercel serves the static Flutter build; the model-serving API uses a separate CPU container. Training, source approval, passage ingestion and optional graph synchronization are offline operations. This separation avoids loading training jobs and document ingestion into web request handlers.')
    add('### 4.1 Longitudinal findings representation')
    add('For a legitimate timestamped cohort, an observation is O=(a,V), where a is age in hours and V is an allowlisted mapping of measurements with known units. A prediction request contains the current observation and strictly earlier, uniquely timed history. Outcomes, culture-result labels and legacy point scores are not predictors. The feature contract extracts current values, missingness and available within-24-hour counts, deltas and least-squares slopes. For measured values v at times t, slope is sum((t-mean(t))*(v-mean(v))) / sum((t-mean(t))^2); it is not a difference per row index. Future observations and duplicate history times are rejected.')
    add('The evidence packet contains scoped patient measurements, relative-time history and retrieved passages with document identity, version, section, page and source URL. Names, medical-record numbers, free-text notes and absolute dates are excluded from cloud prompts. Observed trends are described separately from diagnosis and guideline recommendations. A change in CRP is a recorded measurement change; the language model is not allowed to turn that change into an invented calibrated risk probability. The supplied Kaggle table does not exercise the temporal model features because its identity and timing defects make such reconstruction unsound. Synthetic vignettes exercise the history representation in the evidence branch.')
    add('### 4.2 Reviewed corpus and retrieval')
    add('Production retrieval first requires a current source registry entry with document hash, public URL, reviewer metadata and explicit gestational-age, age and care-setting bounds. A chunk must match the reviewed source version and hash. Unregistered files and unrelated forms are excluded. Full-text PostgreSQL candidates and pgvector candidates are fused using reciprocal rank; an optional Neo4j query adds concept-linked candidate IDs, which must pass the same source and population admission checks. A cross-encoder can rerank admitted candidates. If dense retrieval is unavailable, lexical degradation is explicit; missing reviewed evidence does not trigger a seeded clinical answer.')
    add('The synthetic experiment uses a distinct evaluation-only extraction from the user-supplied May 2026 NICE PDF. Recommendation-level passages retain conditional lists across page breaks, including all conditions of the 36-hour stopping recommendation. Two risk/indicator boxes supplement these passages, producing 132 chunks. The local cropped PDF page number is retained separately from guideline section identifiers. The experimental extraction does not mark the production registry as clinically approved, and other available PDFs are not silently mixed into this benchmark.')
    add('### 4.3 Immutable quotations and multi-role verification')
    add('The initial generator was asked to reproduce verbatim quotes. It sometimes inserted ellipses, changed wording or joined noncontiguous phrases, causing exact-source validation to fail. The revised contract supplies immutable E#Q# source-span identifiers. The model returns claim text, section and quote IDs; the server materializes exact source text and source labels. Unknown IDs, malformed claims, duplicate claim identifiers and unsupported numeric medication/fluid doses are rejected. Selecting an existing quote proves traceability only; it does not prove that the quote entails the claim.')
    add('A LangGraph state machine runs synthesis, then source-entailment and neonatal-safety auditors, followed by release. Auditors receive the same source packet and draft, without generator rationale or each other\'s decisions. They must cover every claim and reject unsupported inferences, wrong populations, assumed-normal missing data and unsafe reassurance. Unanimous acceptance and successful structural/source checks release the unchanged draft for clinician review. Dissent, malformed verdicts or service outages withhold the complete plan. There is no silent repair loop. The same openai/gpt-oss-120b model supplies all roles, so independence is procedural and correlated errors remain possible.')
    add('### 4.4 Application and deployment controls')
    add('Supabase bearer tokens establish identity; encounter ownership is checked before loading history. Administrative authorization uses server-controlled app metadata. Body-size limits, request deadlines, no-store responses and append-only decision metadata support operation and audit. Model artifacts are JSON rather than executable pickle and require a configured digest. Client builds contain only public API and Supabase configuration. The web bundle was scanned for environment assets and configured server credentials, with no matches. These engineering controls do not establish an institutional compliance certification.')
    add('## 5. Supplied-label model development')
    add('Two experiments use the same fixed patient-ID partition assignment: all supplied neonatal ages and postnatal days 0-2. Patient identifiers are sorted and split with seed 31 into fit (55%), calibration (15%), model-selection validation (15%) and final test (15%) groups. This is random patient-ID isolation, not temporal or external validation. The age-restricted cohort inherits those assignments; its retained group proportions can differ. Neither Patient_ID nor Observation_Hour is a predictor.')
    add('Table 2. Partition sizes; each cell gives observations / supplied patient identifiers.')
    add(table(['Cohort','Fit','Calibration','Validation','Test'],[[e['cohort'].replace('_',' ')]+[f"{p['rows']:,} / {p['patient_ids']:,}" for p in e['partitions']] for e in ml['experiments']]))
    add('Numeric inputs retain the CSV\'s supplied units. Sex and delivery mode use training-observed category indicators. Median imputation, centering and scaling are fitted only on the fit partition; a missingness indicator accompanies each design column. A logistic classifier uses C=1 and a 150-tree random forest uses maximum depth 10 and minimum leaf size 15. These fixed settings are not optimized on the test set. Observations receive inverse within-patient-frequency weights for fitting and calibration, reducing dominance by identifiers with more rows. Final discrimination and calibration metrics describe observations; the uncertainty analysis clusters resampling by identifier.')
    add('Each classifier is calibrated on its separate calibration partition with logistic scaling of clipped probability logits. Model choice minimizes validation Brier score, independently in each cohort. A research threshold is the fifth percentile of positive validation predictions, targeting approximately 95% validation sensitivity without encoding an antibiotic rule. The untouched test partition then provides AUROC, average precision (AUPRC), Brier score, sensitivity, specificity, PPV and calibration bins. A constant training-prevalence predictor is retained as a reference baseline. Three hundred bootstrap replicates resample test identifiers with replacement, retaining all their observations, to estimate percentile 95% intervals for the selected model.')
    add('Portable JSON stores preprocessing, calibration parameters and logistic coefficients or tree arrays. Exported predictions match scikit-learn within 1e-7 on the test design matrix. Tree inference explicitly uses float32 inputs before threshold comparisons, matching scikit-learn and preventing boundary disagreements. These research artifacts identify their target as supplied Sepsis_Label and are intentionally incompatible with the clinical eos-landmark-v1 contract. They cannot become eligible EOS models merely by being placed in the application\'s artifact directory.')
    add('## 6. Synthetic RAG experimental protocol')
    add('### 6.1 Cases, references and retrieval ablations')
    add('Eighteen synthetic vignettes cover six families with three parameter variants each: respiratory deterioration, CRP-only reasoning, incomplete stopping criteria, initial investigations, an isolated known risk factor, and missing results. Histories contain two earlier assessments and a current assessment, with known gestation, age and hospital setting. All cases and engineering-authored source-based references were written before inference and are stored with a fixed SHA-256. The references are not clinical reports from the CSV or MIMIC. Related variants share questions and references, so the effective scenario diversity is six families rather than eighteen independent clinical presentations.')
    add('For each query, BM25 ranks tokenized passages and MiniLM-L6-v2 ranks normalized passage embeddings by exact cosine similarity. Hybrid ranks use reciprocal-rank fusion with offset 60. The concept variant adds reciprocal ranks from deterministic passage-concept links. Each method returns four passages. Gold relevant section/box IDs are manually specified in the engineering fixture; Recall@4 is the retrieved fraction of those IDs and MRR@4 uses the rank of the first relevant ID. These are offline exact-search and concept-expansion ablations, not throughput or accuracy measurements of deployed pgvector or Neo4j services.')
    add('### 6.2 Paired verification ablation and provider failures')
    add('Generation uses the concept-expanded hybrid packet under the fixed evaluation protocol, even when that variant performs worse in the retrieval ablation. The configured Groq model is openai/gpt-oss-120b, temperature 0, low reasoning effort, JSON response mode and a 3,000-token completion ceiling. One draft per case is paired with an unverified arm that emits that draft and a verified arm that either emits the identical draft or withholds it. This isolates release filtering; it does not test whether a verifier can rewrite a better answer. Both conditional released-only quality and all-case quality are reported.')
    add('The first quote-echo run and the revised quote-ID run are retained separately. The same development cases informed the engineering change; they are not relabeled as an untouched held-out test. Cases with incomplete provider execution are excluded from model-quality comparisons, with the same eligible case population used in both paired arms. Completed malformed answers and verifier disagreements remain quality outcomes. Only provider-blocked steps are retried with bounded, paced requests; existing answers, including schema errors and completed dissent, are replayed verbatim. Operational attempts are stored separately. Regression tests prevent an audit of a missing draft being reused for a later draft. This eligibility rule separates model performance from service availability.')
    add('### 6.3 Automatic metrics, model-based judging and fault injection')
    add('BLEU-4 uses sacreBLEU corpus aggregation, 13a tokenization and exponential smoothing, divided by 100 for a 0-1 scale. METEOR uses NLTK with lowercased WordPunct tokens, Porter stemming and WordNet matching. ROUGE-1, ROUGE-2 and ROUGE-L are stemmed F1. BERTScore uses unrescaled contextual token alignment without IDF: DistilBERT-base-uncased layer 5 and RoBERTa-large layer 17. Versions and BERTScore configuration hashes are saved. Token-length truncation is counted. Surface and embedding alignment do not establish medical correctness.')
    add('A separate prompt, blind to the arm label and previous auditor decisions, judges each available draft against the case, sources and frozen reference. It assigns integer 1-5 scores for grounding, patient fidelity, completeness, actionability and uncertainty handling, plus an unsafe-claim count. The same model is used as generator, auditor and judge; the judge is therefore a dependent semantic proxy with potential shared errors and reference bias. Because the verified arm releases unchanged text, its conditional judge scores reuse the same draft judgment. Withheld answers receive zero all-case alignment but have no meaningful judge score; judge means therefore include an explicit available-case denominator.')
    add('Twelve injected drafts, four fault types with three variants each, test negation reversal, omitted stopping conditions, an invented dose and fabricated normal findings. Their source labels and excerpts are real evaluation-corpus spans, so citation existence alone cannot validate their content. The unverified arm would emit all injected drafts. The verified arm is measured for withholding, with deterministic dose rejection distinguished from semantic-auditor rejection and service-unavailable withholding. These deliberately enriched faults are not an estimate of naturally occurring hallucination prevalence.')
    add('## 7. Results')
    add('### 7.1 Supplied-label classification and calibration')
    add('Table 3. Final test metrics. Thresholds were selected on validation data; neither threshold is a treatment rule.')
    rows=[]
    for e in ml['experiments']:
        for kind in ['logistic','forest']:
            m=e['candidates'][kind]['test'];rows.append(['All ages' if e['cohort']=='all_neonatal_ages' else 'Days 0-2',kind]+[number(m[k]) for k in ['auroc','auprc','brier','sensitivity','specificity']])
    add(table(['Cohort','Model','AUROC','AUPRC','Brier','Sensitivity','Specificity'],rows))
    add('Both cohorts select the forest by validation Brier score. The all-age test set contains 14,937 observations from 3,000 supplied identifiers; the age-restricted test set contains 1,598 observations from 509 identifiers. These identifiers are disjoint from development groups. The validation operating points do not force test sensitivity to equal the development target: age-restricted forest sensitivity is '+number(ml['experiments'][1]['candidates']['forest']['test']['sensitivity'])+'. This distinction matters when describing a high-sensitivity workflow.')
    add('Table 4. Selected-forest patient-cluster bootstrap 95% intervals (300 replicates).')
    add(table(['Metric','All ages','Days 0-2'],[[k.upper() if k in ['auroc','auprc'] else k.title()]+['['+', '.join(number(x) for x in e['selected_test_cluster_bootstrap_95ci'][k])+']' for e in ml['experiments']] for k in ['auroc','auprc','brier','sensitivity','specificity']]))
    add('The days-0-2 specificity interval is degenerate at 1 because no false positives occurred at the selected threshold in that supplied-label test set. Resampling the same observed records cannot create unseen errors; the interval does not establish perfect specificity in a new population.')
    add('![Figure 2. Held-out supplied-label calibration and Brier scores. The class label and source-data defects constrain interpretation.](output/research/figures/ml_results.png)')
    add(f'''The near-perfect discrimination is not taken as proof of a mature EOS forecaster. As a post-hoc separability diagnostic, a depth-3 decision tree using a small laboratory/vital subset obtains accuracy {number(diagnostic['heldout_accuracy'])} and AUROC {number(diagnostic['heldout_auroc'])}. Its principal splits involve PCT and CRP, consistent with strongly separable supplied labels. This diagnostic was not part of model selection, does not establish how labels were created, and could reflect either biological selection or data/label-generation mechanisms. Lack of onset and result-availability times also prevents excluding concurrent diagnostic/workflow leakage. Narrow bootstrap intervals quantify sampling variability under the supplied records, not uncertainty about their provenance or outcome validity.''')
    add('### 7.2 Retrieval and concept expansion')
    add('Table 5. Retrieval ablation over 18 synthetic queries and 132 evaluation passages.')
    add(table(['Retriever','Recall@4','MRR@4'],[[k.replace('_',' ')]+[number(v[m]) for m in ['recall_at_4','mrr_at_4']] for k,v in retrieval['summary'].items()]))
    add('Sparse and dense methods are complementary in this fixture: reciprocal-rank hybrid has the highest measured recall. Adding broad concept links reduces Recall@4 from '+number(retrieval['summary']['hybrid']['recall_at_4'])+' to '+number(retrieval['summary']['hybrid_concepts']['recall_at_4'])+'. Common terms such as antibiotics, culture and serial assessment connect passages from different neonatal contexts, which can dilute precise recommendation matching. This result supports leaving optional production graph expansion disabled by default until independently evaluated; it does not support a blanket claim that a graph improves this application.')
    add('### 7.3 Generation, verification and coverage')
    firstdraft=sum(bool(x['result'].get('draft')) for x in initial)
    firstsource=sum(bool(x['result'].get('draft')) and bool(x['result'].get('citation_errors')) for x in initial)
    add(f'''Among the {len(initial)} eligible completed cases in the initial quote-echo run, {firstdraft} produced parsed drafts, none were released, and {firstsource} failed exact-source checks. The revised run has {rag['n']} eligible cases, {rag['generated']} parsed drafts and {rag['released']} releases. These different completed populations preclude attributing the change in overall draft yield solely to quote IDs. A valid quote ID eliminates quote-echo errors for that support span, but does not prevent unsupported text or guarantee that both auditors accept a complete plan.''')
    add('Table 6. Paired lexical alignment. Verified all-case scores count each withheld response as empty; conditional scores describe a selected subset.')
    names={'without_verification':'Unverified, all cases','without_verification_generated_only':'Unverified, generated only','with_verification_all_cases':'Verified, all cases','with_verification_released_only':'Verified, released only'}
    add(table(['Arm','N','Coverage','BLEU-4','METEOR','ROUGE-1','ROUGE-2','ROUGE-L'],[[names[k],v['denominator'],number(v['coverage'],3)]+[number(v['metrics'][m]) for m in ['corpus_bleu4','meteor','rouge1','rouge2','rougeL']] for k,v in arms.items()]))
    add('Table 7. Semantic alignment with fixed BERTScore configurations.')
    add(table(['Arm','DistilBERT P','DistilBERT R','DistilBERT F1','RoBERTa F1'],[[names[k]]+[number(v['metrics'][m]) for m in ['bert_precision','bert_recall','bert_f1','roberta_f1']] for k,v in arms.items()]))
    generated_arm=arms['without_verification_generated_only']
    add(f'''Among the 15 available unverified drafts, DistilBERT F1 is {number(generated_arm['metrics']['bert_f1'])} and RoBERTa F1 is {number(generated_arm['metrics']['roberta_f1'])}. Among the four released drafts, these values are {number(released['metrics']['bert_f1'])} and {number(released['metrics']['roberta_f1'])}. Thus verification does not improve conditional semantic alignment in this fixture. Higher released-subset judge grounding, when observed, is a different, fallible metric and accompanies a large loss of coverage. The study does not support a general answer-quality improvement claim.''')
    delta=rag['paired_all_case_bert_f1_delta']
